<?php
declare(strict_types=1);
require_once __DIR__ . '/_init.php';

$db = database_connection();
$counts = ['total' => 0, 'New' => 0, 'Contacted' => 0, 'Won' => 0];
$countStmt = $db->query("SELECT COUNT(*) AS total, SUM(status = 'New') AS new_count, SUM(status = 'Contacted') AS contacted_count, SUM(status = 'Won') AS won_count FROM leads");
$row = $countStmt->fetch() ?: [];
$counts['total'] = (int) ($row['total'] ?? 0);
$counts['New'] = (int) ($row['new_count'] ?? 0);
$counts['Contacted'] = (int) ($row['contacted_count'] ?? 0);
$counts['Won'] = (int) ($row['won_count'] ?? 0);
$recentStmt = $db->query("SELECT id, created_at, name, phone, product, status FROM leads ORDER BY created_at DESC, id DESC LIMIT 8");
$recent = $recentStmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Dashboard | Print Advertising</title><link rel="icon" href="/images/favicons/favicon.png"><style>
*{box-sizing:border-box}body{margin:0;background:#f7f6fa;color:#191632;font:14px/1.5 Arial,sans-serif}.top{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:14px max(18px,calc((100% - 1120px)/2));background:#191632;color:#fff}.top img{width:155px;max-height:52px;object-fit:contain}.top a{color:#fff}.nav{display:flex;gap:14px;align-items:center}.wrap{width:min(1120px,calc(100% - 32px));margin:26px auto}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:18px 0 24px}.card,.panel{border:1px solid #e8e5ee;border-radius:10px;background:#fff}.card{padding:18px}.card span{display:block;color:#716d7e;font-size:12px}.card strong{font-size:27px}.panel{overflow:auto}.panel h1{margin:0;padding:20px 20px 10px;font-size:21px}.table{width:100%;border-collapse:collapse;min-width:650px}.table th,.table td{padding:12px 15px;border-top:1px solid #eeeaf3;text-align:left}.table th{font-size:11px;color:#716d7e;text-transform:uppercase}.status{font-weight:700}.button{display:inline-block;padding:9px 13px;border-radius:6px;background:#6515d4;color:#fff;text-decoration:none}.empty{padding:18px}@media(max-width:650px){.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.top{align-items:flex-start}.nav{flex-wrap:wrap;justify-content:flex-end}}
</style></head><body><header class="top"><a href="/admin/index.php"><img src="/images/logo.webp" alt="Print Advertising"></a><nav class="nav"><a href="/admin/leads.php">Enquiries</a><a href="/admin/settings.php">Settings</a><a href="/admin/logout.php">Log out</a></nav></header><main class="wrap"><h1>Enquiry dashboard</h1><section class="stats" aria-label="Enquiry totals"><div class="card"><span>Total enquiries</span><strong><?= $counts['total'] ?></strong></div><div class="card"><span>New enquiries</span><strong><?= $counts['New'] ?></strong></div><div class="card"><span>Contacted enquiries</span><strong><?= $counts['Contacted'] ?></strong></div><div class="card"><span>Completed enquiries</span><strong><?= $counts['Won'] ?></strong></div></section><section class="panel"><h1>Recent enquiries <a class="button" href="/admin/leads.php">Manage all</a></h1><?php if (!$recent): ?><p class="empty">No enquiries have been submitted yet.</p><?php else: ?><table class="table"><thead><tr><th>Date</th><th>Name</th><th>Phone</th><th>Product</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($recent as $lead): ?><tr><td><?= escape_html(date('Y-m-d H:i', strtotime((string) $lead['created_at']))) ?></td><td><?= escape_html($lead['name']) ?></td><td><?= escape_html($lead['phone']) ?></td><td><?= escape_html($lead['product'] ?: '—') ?></td><td class="status"><?= escape_html($lead['status']) ?></td><td><a href="/admin/lead.php?id=<?= (int) $lead['id'] ?>">View</a></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section></main></body></html>
